contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        assert(reverted
            ? (depositsAfter == depositsBefore && balAfter == balBefore)
            : (depositsAfter == depositsBefore && balAfter == balBefore - amount)
        );
    }

    receive() external payable {}
}

